'use strict';

// MODULES //

var tape = require( 'tape' );
var PINF = require( '@stdlib/constants-float64-pinf' );
var NINF = require( '@stdlib/constants-float64-ninf' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var isNegativeZero = require( '@stdlib/math-base-assert-is-negative-zero' );
var isPositiveZero = require( '@stdlib/math-base-assert-is-positive-zero' );
var ceil = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ceil, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns the largest integer greater than or equal to a given number', function test( t ) {
	t.strictEqual( ceil( -4.2 ), -4.0, 'equals -4' );
	t.strictEqual( ceil( 9.99999 ), 10.0, 'equals 10' );
	t.strictEqual( ceil( 0.0 ), 0.0, 'equals 0' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', function test( t ) {
	var val = ceil( NaN );
	t.strictEqual( isnan( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var val = ceil( -0.0 );
	t.strictEqual( isNegativeZero( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var val = ceil( +0.0 );
	t.strictEqual( isPositiveZero( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var val = ceil( PINF );
	t.strictEqual( val, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var val = ceil( NINF );
	t.strictEqual( val, NINF, 'returns expected value' );
	t.end();
});","lineStart":1,"lineEnd":75,"totalLines":75,"truncated":false}},"title":"repos\pc-lib-3456\math-base-special-ceil\test\test.js","time":{"start":1783768930052,"end":1783768930066}},"id":"prt_f50e9d13d001djLi6ME9Ki6d62","sessionID":"ses_0af174057ffeX8NMqrEKOwX9RU","messageID":"msg_f50e9a7a6001o74BCqV9gt0BB9"}}

